from dataclasses import field


@dataclass
class SqlResponse:
    rows : list[dict] = None
    last_row_id: int | None = None
    rows_affected: int = 0
    

def execute_sql(sql: str, db_path: str, params: tuple = (), debug_prn: bool = False) -> SqlResponse:
    """Run one SQL statement that CHANGES the database (CREATE, INSERT, UPDATE, DELETE).

    Args:
        sql: the SQL statement, with `?` placeholders for the data.
        db_path: path to the SQLite file.
        params: the values to fill into the placeholders.
        debug_prn: if True, print the SQL we ran.

    Returns:
        The id of the new row (for INSERTs).
    """
    if debug_prn:
        print(f"executing SQL on {db_path}:\n{sql}")

    try:
        with sqlite3.connect(db_path) as conn:
            cursor = conn.cursor()
            cursor.execute(sql, params)
            conn.commit()

        return SqlResponse(last_row_id=cursor.lastrowid, rows_affected=cursor.rowcount)

    except sqlite3.OperationalError as e:
        # the SQL itself was wrong — a typo, a missing table, a missing column
        print(f"SQL error: {e}\nwhile running:\n{sql}")
        raise

    except sqlite3.IntegrityError as e:
        # the SQL was fine, but the data broke a table rule (NOT NULL, UNIQUE, ...)
        print(f"Database rejected the data: {e}")
        raise

    except sqlite3.Error as e:
        # any other SQLite problem
        print(f"SQLite error: {e}")
        raise


def query_sql(sql: str, db_path: str, params: tuple = (), debug_prn: bool = False) -> SqlResponse:
    """Ask the database a question (SELECT) and return the matching rows.

    Args:
        sql: the SELECT statement, with `?` placeholders for the data.
        db_path: path to the SQLite file.
        params: the values to fill into the placeholders.
        debug_prn: if True, print the SQL and how many rows came back.

    Returns:
        One dictionary per row.
    """
    if debug_prn:
        print(f"querying {db_path}:\n{sql}")

    try:
        with sqlite3.connect(db_path) as conn:
            conn.row_factory = sqlite3.Row  # rows come back with column NAMES, not just positions
            cursor = conn.cursor()
            cursor.execute(sql, params)
            rows = [dict(row) for row in cursor.fetchall()]

        if debug_prn:
            print(f"{len(rows)} row(s) returned")

        return SqlResponse(rows=rows)

    except sqlite3.OperationalError as e:
        # the SQL itself was wrong — a typo, a missing table, a missing column
        print(f"SQL error: {e}\nwhile running:\n{sql}")
        raise

    except sqlite3.Error as e:
        # any other SQLite problem
        print(f"SQLite error: {e}")
        raise


