import datetime as dt
from .detect import Detection, DetectionBoundingBox
from PIL import Image

@dataclass
class Sighting:
    species: str
    confidence: float
    image_bytes: bytes = field(repr=False)
    bounding_box: DetectionBoundingBox | None = None
    timestamp: dt.datetime | None = None
    id: int | None = None
    submitted_by: str | None = None  # Slack user id; None = the backyard camera

    def __post_init__(self):
        if self.timestamp is None:
            self.timestamp = dt.datetime.now()

    @property
    def image(self) -> Image.Image:
        """Return the image as a PIL Image object."""
        from io import BytesIO

        return Image.open(BytesIO(self.image_bytes))
    
    @property
    def cropped_image(self) -> Image.Image:
        """Return the cropped image as a PIL Image object."""
        from io import BytesIO

        if self.bounding_box is None:
            raise ValueError("No bounding box available for this sighting.")

        image = Image.open(BytesIO(self.image_bytes))
        return image.crop((self.bounding_box.x_min, self.bounding_box.y_min, self.bounding_box.x_max, self.bounding_box.y_max))

    @classmethod
    def from_dict(cls, obj: dict) -> "Sighting":
        """Rebuild a Sighting from a database row."""
        bounding_box = None
        if obj["bbox_x_min"] is not None:
            bounding_box = DetectionBoundingBox(
                x_min=obj["bbox_x_min"],
                y_min=obj["bbox_y_min"],
                x_max=obj["bbox_x_max"],
                y_max=obj["bbox_y_max"],
            )

        return cls(
            id=obj["id"],
            timestamp=dt.datetime.fromisoformat(obj["timestamp"]),
            species=obj["species"],
            confidence=obj["confidence"],
            image_bytes=obj["image_bytes"],
            bounding_box=bounding_box,
            submitted_by=obj.get("submitted_by"),
        )

    @classmethod
    def from_detection(cls, detection: Detection) -> "Sighting":
        if detection.Classifier is None:
            raise ValueError(f"No classifier configured for label: {detection.label}")

        return cls(
            species=detection.Classifier.species,
            confidence=detection.Classifier.confidence,
            image_bytes=detection.image_bytes,
            bounding_box=detection.BoundingBox,
        )


