import datetime as dt


CREATE_SIGHTINGS_TABLE_SQL = """
    CREATE TABLE IF NOT EXISTS sightings (
        id              INTEGER PRIMARY KEY AUTOINCREMENT,
        timestamp       TEXT    NOT NULL,
        species         TEXT    NOT NULL,
        confidence      REAL    NOT NULL,
        image_bytes     BLOB    NOT NULL,
        bbox_x_min      INTEGER,
        bbox_y_min      INTEGER,
        bbox_x_max      INTEGER,
        bbox_y_max      INTEGER, 
        submitted_by    TEXT,

        UNIQUE(timestamp, species)
    )
    """

DROP_SIGHTINGS_TABLE_SQL = """
    DROP TABLE IF EXISTS sightings
    """

CLEAR_SIGHTINGS_TABLE_SQL = """
    DELETE FROM sightings
    """

INSERT_SIGHTING_SQL = """
    INSERT INTO sightings (
        timestamp, species, confidence, image_bytes,
        bbox_x_min, bbox_y_min, bbox_x_max, bbox_y_max,
        submitted_by
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
    """


@dataclass
class SightingStorage:
    cooldown_minutes: int

    
    # --- subclasses MUST provide these (the contract) ---
    def post_sighting(self, sighting: Sighting, debug_prn: bool = False) -> SqlResponse:
        raise NotImplementedError

    def get_sightings(self, species: str | None = None, limit: int = 100, offset: int = 0,
                      submitted_by: str | None = None) -> list[Sighting]:
        """Recent sightings, newest first. Optionally filtered to one species and/or one submitter."""
        raise NotImplementedError

    def get_sighting(self, sighting_id: int) -> Sighting | None:
        """One sighting by its id, or None if it doesn't exist."""
        raise NotImplementedError

    # --- written ONCE, works for every store ---
    def get_previous_sighting_time(self, species: str) -> dt.datetime | None:
        # only uses the contract methods above — so every store gets it for free
        sightings = self.get_sightings(species=species, limit=1)

        if not sightings:
            return None

        return sightings[0].timestamp

    def calc_should_record_sighting(self, species:str, sighting_time: dt.datetime) -> bool:

        previous_sighting_time : dt.datetime | None = self.get_previous_sighting_time(species)

        if previous_sighting_time is None:
            return True # No previous sighting, so we should record this one

        cutoff_time = sighting_time - dt.timedelta(minutes=self.cooldown_minutes)

        return previous_sighting_time < cutoff_time  # Implement the actual logic to determine if the sighting should be recorded

    def record_sighting(self, sighting: Sighting, debug_prn: bool = False) -> SqlResponse | None:

        if not self.calc_should_record_sighting(species = sighting.species, sighting_time = sighting.timestamp):

            if debug_prn:
                print(  f"skipped: {sighting.species} seen within {self.cooldown_minutes} min")
            return None


        if debug_prn:
            print(f"recording: {sighting.species} seen after cooldown of {self.cooldown_minutes} min")

        return self.post_sighting(sighting, debug_prn=debug_prn)
        


@dataclass
class SqliteSightingStorage (SightingStorage):
    db_path: str

    def __post_init__(self):
        self._create_sightings_table()
        self._migrate_sightings_table()

    def _create_sightings_table(self, debug_prn: bool = False) -> SqlResponse:
        return execute_sql(CREATE_SIGHTINGS_TABLE_SQL, db_path=self.db_path, debug_prn=debug_prn)

    def _migrate_sightings_table(self, debug_prn: bool = False) -> None:
        """Upgrade databases created before `submitted_by` existed.

        `CREATE TABLE IF NOT EXISTS` only helps NEW databases — an old file keeps
        its old columns. So we ask SQLite what columns the table has, and add
        the missing one. This is a (tiny) database migration."""
        response = query_sql("SELECT name FROM pragma_table_info('sightings')", db_path=self.db_path)
        column_names = [row["name"] for row in response.rows]

        if "submitted_by" not in column_names:
            execute_sql("ALTER TABLE sightings ADD COLUMN submitted_by TEXT",
                        db_path=self.db_path, debug_prn=debug_prn)

    
    def post_sighting(self, sighting: Sighting, debug_prn: bool = False  ) -> SqlResponse:
        
        bbox = sighting.bounding_box  # may be None — the table allows a sighting with no box

        return execute_sql(
            INSERT_SIGHTING_SQL,
            db_path=self.db_path,
            params=(
                sighting.timestamp.isoformat(timespec="seconds"),
                sighting.species,
                sighting.confidence,
                sighting.image_bytes,
                bbox.x_min if bbox else None,
                bbox.y_min if bbox else None,
                bbox.x_max if bbox else None,
                bbox.y_max if bbox else None,
                sighting.submitted_by,
            ),
            debug_prn=debug_prn,
        )


    def get_sightings(self, 
                      species: str | None = None,
                      limit: int = 100,
                      offset: int = 0,
                      submitted_by: str | None = None,
                      debug_prn: bool = False) -> list[Sighting]:
        
        sql = "SELECT * FROM sightings"
        where = []
        params = []

        if species:
            where.append("species = ?")
            params.append(species)

        if submitted_by:
            where.append("submitted_by = ?")
            params.append(submitted_by)
        
        if where:
            sql += " WHERE " + " AND ".join(where)

        sql += " ORDER BY timestamp DESC LIMIT ? OFFSET ?"
        params.append(limit)
        params.append(offset)

        response = query_sql(sql, db_path=self.db_path, params=tuple(params), debug_prn=debug_prn)

        return [Sighting.from_dict(row) for row in response.rows]

    def get_sighting(self, sighting_id: int, debug_prn: bool = False) -> Sighting | None:
        response = query_sql(
            "SELECT * FROM sightings WHERE id = ?",
            db_path=self.db_path,
            params=(sighting_id,),
            debug_prn=debug_prn,
        )

        if not response.rows:
            return None

        return Sighting.from_dict(response.rows[0])


    def clear_sightings_table(
        self,
        is_drop: bool = False,
        debug_prn: bool = False,
    ) -> SqlResponse:
        
        confirmation = input(
            "Are you sure you want to clear the sightings table? "
            "This action cannot be undone. Type 'yes' to confirm: "
        )

        if confirmation.lower() != "yes":
            raise Exception("Operation cancelled.")

        if is_drop:
            return execute_sql(DROP_SIGHTINGS_TABLE_SQL, db_path=self.db_path, debug_prn=debug_prn)

        return execute_sql(CLEAR_SIGHTINGS_TABLE_SQL, db_path=self.db_path, debug_prn=debug_prn)

        
